void to_lower(char s[]){
    for(size_t i = 0; i < strlen(s); i++)
        s[i] = (char)tolower((unsigned char)s[i]);
}

char s[] = "codelab BLOG";
to_lower(s);
printf("%s\n", s);   // codelab blog

void to_lower(const char src[], char dst[]){
    int i = 0;
    for(; src[i] != '\0'; i++){
        dst[i] = src[i];
        if(src[i] >= 'A' && src[i] <= 'Z') dst[i] += 32;
    }
    dst[i] = '\0';
}

char s[] = "codelab BLOG strING";
for(char *p = s; *p != '\0'; p++)
    *p = (char)tolower((unsigned char)*p);
printf("Lowercase : %s\n", s);  // codelab blog string

char *str_upper(char *s){
    for(char *p = s; *p; p++)
        *p = (char)toupper((unsigned char)*p);
    return s;
}
printf("%s\n", str_upper(s));   // CODELAB BLOG STRING
